sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_mode;
uniform float amzp_amount;
uniform float2 amzp_center;
uniform float amzp_radius;
uniform float amzp_rotation;
uniform float amzp_repeats;
uniform float amzp_twist;
uniform float amzp_zoom;
uniform float amzp_flipR;
uniform float amzp_spin;
uniform float amzp_scroll;
uniform float amzp_pulse;
uniform float amzp_pulseSpeed;
uniform float amzp_depth;
uniform float amzp_spiralTwist;
uniform float amzp_centerFade;
layout(color) uniform half4 amzp_fadeColor;
uniform float amzp_edge;
uniform float amzp_seam;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    const float PI = 3.14159265;
    const float TAU = 6.2831853;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2 rot2(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float tm() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_autoSpeed : amzp_progress; }
    float4 src(float2 s) {
        if (int(amzp_edge) == 0) s = fract(s);
        else if (int(amzp_edge) == 1) s = 1.0 - abs(mod(s, 2.0) - 1.0);
        else if (int(amzp_edge) == 2) s = clamp(s, 0.0, 1.0);
        else if (s.x < 0.0 || s.y < 0.0 || s.x > 1.0 || s.y > 1.0) return float4(0.0);
        return amzTexture(0, l2s(s));
    }
    float4 seamSrc(float u, float v) {
        float fu = fract(u);
        float4 c = src(float2(fu, v));
        if (amzp_seam <= 0.0) return c;
        float d = min(fu, 1.0 - fu);
        float hw = amzp_seam * 0.5;
        if (d >= hw) return c;
        float4 o = src(float2(1.0 - fu, v));
        return mix(c, o, 0.5 * (1.0 - d / hw));
    }
    float4 warp(float2 p, float2 W, float R, float t, float2 cpx) {
        float r = length(p) / R;
        float a = atan(p.y, p.x) + radians(amzp_rotation + amzp_spin * t);
        float z = max(amzp_zoom, 0.0001);
        float rn = (amzp_flipR>0.5) ? 1.0 / max(r, 0.0001) : r;
        if (int(amzp_mode) == 0) {
            float u = (a / TAU + 0.5 + rn * amzp_twist * 0.1) * amzp_repeats;
            float v = rn / z - amzp_scroll * t;
            return seamSrc(u, v);
        }
        if (int(amzp_mode) == 1) {
            float2 q = p / W + 0.5;
            float ang = (q.x * amzp_repeats + t * amzp_spin / 360.0) * TAU + radians(amzp_rotation);
            float rad = ((amzp_flipR>0.5) ? 1.0 - q.y : q.y) * z + amzp_scroll * t;
            rad += amzp_twist * 0.1 * q.x;
            float2 sp = float2(cos(ang), sin(ang)) * rad * R;
            return src((sp + cpx) / W + 0.5);
        }
        if (int(amzp_mode) == 2) {
            float u = (a / TAU + 0.5) * amzp_repeats + amzp_twist * 0.1 / max(r, 0.05);
            float v = amzp_depth * 0.5 / max(rn, 0.0001) / z + amzp_scroll * t;
            float4 c = seamSrc(u, v);
            float f = amzp_centerFade > 0.0 ? smoothstep(0.0, amzp_centerFade, rn) : 1.0;
            return mix(float4(amzp_fadeColor.rgb * amzp_fadeColor.a, amzp_fadeColor.a), c, f);
        }
        if (int(amzp_mode) == 3) {
            float lr = log(max(rn, 0.00001));
            float u = (a / TAU + 0.5) * amzp_repeats + lr * amzp_spiralTwist;
            float v = lr * amzp_depth * 0.5 / z - lr * amzp_twist * 0.05 - amzp_scroll * t;
            float4 c = seamSrc(u, v);
            float f = amzp_centerFade > 0.0 ? smoothstep(0.0, amzp_centerFade, rn) : 1.0;
            return mix(float4(amzp_fadeColor.rgb * amzp_fadeColor.a, amzp_fadeColor.a), c, f);
        }
        float sa = a * amzp_repeats - radians(amzp_rotation + amzp_spin * t) * (amzp_repeats - 1.0) + amzp_twist * r * PI * 0.5;
        float sr = (rn / z + amzp_scroll * t * 0.1) * R;
        float2 sp = float2(cos(sa), sin(sa)) * sr;
        return src((sp + cpx) / W + 0.5);
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = amzTexture(0, amzScreenNorm());
        float px = pxs();
        float t = tm();
        float2 cpx = float2(amzp_center.x, -amzp_center.y) * px;
        float R = 0.5 * min(W.x, W.y) * max(amzp_radius, 0.001) * (1.0 + amzp_pulse * sin(t * amzp_pulseSpeed * TAU) * 0.5);
        int q = int(clamp(floor(amzp_quality + 0.5), 1.0, 4.0));
        float4 acc = float4(0.0);
        float n = 0.0;
        for (int i = 0; i < 4; i++) {
            if (i >= q) break;
            for (int j = 0; j < 4; j++) {
                if (j >= q) break;
                float2 o = (float2(float(i), float(j)) + 0.5) / float(q) - 0.5;
                float2 p = (uv - 0.5) * W + o - cpx;
                if (int(amzp_mode) == 1) p = (uv - 0.5) * W + o;
                acc += warp(p, W, R, t, cpx);
                n += 1.0;
            }
        }
        float4 c = acc / max(n, 1.0);
        c = mix(orig, c, clamp(amzp_amount, 0.0, 1.0));
        amzOutput = (amzp_overdrawOn>0.5) ? c : c * orig.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
